use std::collections::HashMap;

fn two_sum(nums: &Vec<u32>, target: u32) -> (usize, usize) {
    let n = nums.len();
    assert!(n >= 2);

    // Map value -> earliest index where it occurred.
    // We iterate i from left to right; for each i, we check if there exists
    // a j < i such that nums[j] + nums[i] == target.
    // This guarantees the first time we find a pair, it is lexicographically smallest
    // (smallest second index i; and for that i, smallest first index j).
    let mut earliest: HashMap<u32, usize> = HashMap::new();

    for i in 0..n {
        let x = nums[i];
        if let Some(need) = target.checked_sub(x) {
            if let Some(&j) = earliest.get(&need) {
                // j < i by construction (only inserted from earlier indices)
                return (j, i);
            }
        }
        // Only record the earliest index for each value.
        earliest.entry(x).or_insert(i);
    }

    // Problem statement guarantees a solution exists.
    unreachable!("No two-sum pair found, but the problem guarantees existence");
}